// === Tab: mySketch ===
//let a = 0.008;  // three wings
//let m = -0.496; // three wings
let a = 0.01;                // five wings
let m = cos(4*PI/5) + 0.008; // five wings
let b = 0.05;
let cx = 1; // value of current x
let cy = 1; // value of current y
let d = 1; // diameter of an ellipse
let s = 0.05; // change scale of the map
let t = 0; // keep track of time

function setup() {
  createCanvas(1200, 650);
  background(20, 10, 10);
  noStroke();
  //frameRate(120);
}

function draw() {
  t++;
  for (i = 0; i < 30; i++) {
    // update x and y
    let newX = cy + a*(1-b*sq(cy))*cy + m*cx + 2*(1-m)*sq(cx) / (1 + sq(cx));
    let newY = -cx + m*newX + 2*(1-m)*sq(newX) / (1 + sq(newX));

    // calculate the distance between the new point and the center
    let distance = dist(int(width / 2 + newX/s), int(height / 2 + newY/s), (width/2), height/2);

    // let accoriding to the distance
    let n = noise(float(t)/30);

    // draw ellipse
    if (distance >= 0 && distance < 100*n) fill(202, 114, 65); //fill(255, 0, 0);
    else if (distance >= 100*n && distance < 200*n) fill(182, 134, 85); //fill(255, 255, 0);  
    else if (distance >= 200*n && distance < 350*n) fill(162, 164, 105); //fill(0, 255, 0); 
    else if (distance >= 350*n && distance < 500*n) fill(142, 204, 125); //fill(0, 0, 255); 
    else fill(122, 254, 205); //fill(255);
    ellipse(int(width / 2 + newX/s), int(height / 2 + newY/s), d, d);

    ////drawing in line is also interesting!
    if (distance >= 0 && distance < 320*n) stroke(202, 114, 65, 5); //fill(255, 0, 0);
    else if (distance >= 320*n && distance < 420*n) stroke(182, 134, 85, 5); //fill(255, 255, 0);  
    else if (distance >= 420*n && distance < 520*n) stroke(162, 164, 105, 5); //fill(0, 255, 0); 
    else if (distance >= 520*n && distance < 620*n) stroke(142, 204, 125, 5); //fill(0, 0, 255); 
    else stroke(122, 254, 205, 5); //fill(255);
    line(int(width / 2 + newX/s), int(height / 2 + newY/s), int(width / 2 + cx/s), int(height / 2 + cy/s));

    // save the point to variables
    cx = newX;
    cy = newY;
  }
}

